<div class="soft-card p-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Bahan</th><th>Kategori</th><th>Stok</th><th>Minimum</th><th>Status</th></tr></thead><tbody><?php foreach($items as $it): ?><tr><td><strong><?= htmlspecialchars($it['name']) ?></strong><br><small><?= htmlspecialchars($it['sku']) ?></small></td><td><?= htmlspecialchars($it['category_name']) ?></td><td><?= number_format($it['stock_qty'],2) ?> <?= htmlspecialchars($it['unit_symbol']) ?></td><td><?= number_format($it['min_stock_qty'],2) ?></td><td><span class="badge bg-danger">Perlu Belanja</span></td></tr><?php endforeach; ?></tbody></table></div></div><?php if(!$items): ?><div class="alert alert-success mt-3">Tidak ada bahan low stock.</div><?php endif; ?>
